-- Browser-proven TradingAgents advisory workflow package preset.
-- This SQL seed restores only workflow_packages and workflow_package_versions rows.
-- It intentionally does not create model_connections, secret bindings, runs, or local runtime state.

WITH inserted_package AS (
    INSERT INTO workflow_packages (
        key, name, description, status, draft_source, created_at, updated_at
    )
    SELECT
        'tradingagents_advisory_research',
        'TradingAgents Advisory Research',
        'advisory/research workflow that approximates TradingAgents through SignalDeck package semantics, not LangGraph runtime parity',
        'active',
        convert_from(decode('', 'base64'), 'UTF8'),
        NOW(),
        NOW()
    WHERE NOT EXISTS (
        SELECT 1 FROM workflow_packages
        WHERE key = 'tradingagents_advisory_research'
    )
    RETURNING id
), inserted_version AS (
    INSERT INTO workflow_package_versions (
        package_id, version, manifest_source, manifest_hash, package_definition,
        compiled_plan, compiled_hash, validation_summary, created_at
    )
    SELECT
        inserted_package.id,
        1,
        convert_from(decode('', 'base64'), 'UTF8'),
        'c44f012963dcbe305333edefb0afa889548aac77b285559f8a2a9bb44af3f690',
        convert_from(decode('', 'base64'), 'UTF8')::jsonb,
        convert_from(decode('', 'base64'), 'UTF8')::jsonb,
        '57d087cde3351dbfa00bb4117fde92b2faf2d04066e54e59695cc27a9644f8d2',
        convert_from(decode('', 'base64'), 'UTF8')::jsonb,
        NOW()
    FROM inserted_package
    RETURNING id, package_id
)
UPDATE workflow_packages AS package
SET latest_version_id = inserted_version.id, updated_at = NOW()
FROM inserted_version
WHERE package.id = inserted_version.package_id;
